import { useCallback, useEffect, useId, useRef, useState, type FormEvent, type KeyboardEvent as ReactKeyboardEvent, type ReactNode, type RefObject } from "react";
import {
  approveApproval, approveExpense, approvePurchaseOrder, cancelTransfer, createApproval, createCustomer as persistCustomer,
  closeOfflineWorkspace, createExpense, createPurchaseOrder, createSupplierPayment, db, dismissSyncIssue, enablePushNotifications,
  fetchApprovalsSummary, fetchBranchPerformance, fetchDailySales, fetchExpensesSummary, fetchProfitLoss,
  fetchReplenishmentSuggestions, fulfilTransfer, getSyncIssues, loadFromServer, markNotificationRead,
  pendingSyncCount, prepareOfflineWorkspace, pushNotificationsAvailable, receivePurchaseOrder, receiveTransfer, recordReceipt,
  recordSale, recordTransfer, rejectApproval, rejectExpense,
  type Approval, type ApprovalsSummary, type Branch, type BranchPerformance, type Customer, type Expense,
  type ExpensesSummary, type JournalEntry, type Notification, type Product, type ProfitLoss, type PurchaseOrder,
  type ReplenishmentSuggestion, type StockMovement, type Supplier, type SupplierPayment, type Transfer,
} from "./db/database";
import { getCurrentUser, login, logout, registerDevice, request, type AuthUser } from "./lib/api";
import { canRoleSeeView, type View } from "./permissions";

type Toast = { tone: "success" | "error" | "info"; message: string } | null;
type AppData = {
  branches: Branch[]; products: Product[]; suppliers: Supplier[]; movements: StockMovement[]; transfers: Transfer[];
  purchaseOrders: PurchaseOrder[]; notifications: Notification[]; customers: Customer[]; approvals: Approval[];
  expenses: Expense[]; supplierPayments: SupplierPayment[]; journalEntries: JournalEntry[];
  dailySales: Array<{ day: string; sales_count: number; sales_total: number }>; profitLoss: ProfitLoss | null;
  branchPerformance: BranchPerformance[]; expensesSummary: ExpensesSummary | null; approvalsSummary: ApprovalsSummary | null;
  replenishmentSuggestions: ReplenishmentSuggestion[]; adminUsers: AuthUser[]; pendingSync: number;
};

const emptyData: AppData = { branches: [], products: [], suppliers: [], movements: [], transfers: [], purchaseOrders: [], notifications: [], customers: [], approvals: [], expenses: [], supplierPayments: [], journalEntries: [], dailySales: [], profitLoss: null, branchPerformance: [], expensesSummary: null, approvalsSummary: null, replenishmentSuggestions: [], adminUsers: [], pendingSync: 0 };
const money = new Intl.NumberFormat("en-ZW", { style: "currency", currency: "USD" });
const TRANSFER_FULFIL_ROLES = ["owner", "store_keeper", "super_admin"];
const TRANSFER_RECEIVE_ROLES = ["owner", "store_keeper", "shop_manager", "super_admin"];
const PURCHASE_ORDER_APPROVE_ROLES = ["owner", "accountant", "super_admin"];
const ACCOUNTING_ROLES = ["owner", "accountant", "super_admin"];
const REPLENISHMENT_ROLES = ["owner", "store_keeper", "shop_manager", "super_admin"];
const ANALYTICS_ROLES = ["owner", "accountant", "shop_manager", "super_admin"];
const titles: Record<View, { eyebrow: string; title: string; copy: string }> = {
  overview: { eyebrow: "", title: "Control Room", copy: "The work that needs attention across inventory, movement and approvals." },
  catalogue: { eyebrow: "Inventory", title: "Parts & fitment", copy: "Search the fitment-first catalogue and check branch availability." },
  receipt: { eyebrow: "Inventory", title: "Receive stock", copy: "Post supplier stock into the warehouse ledger." },
  transfer: { eyebrow: "Movement", title: "Branch transfers", copy: "Request, fulfil and receive traceable stock movements." },
  sale: { eyebrow: "Movement", title: "Record a sale", copy: "Issue stock from the shop with an optional customer record." },
  approval: { eyebrow: "Control", title: "Approvals", copy: "Route important operational decisions to the right person." },
  expense: { eyebrow: "Control", title: "Operating expenses", copy: "Record and review branch expenses before they reach the journal." },
  purchase: { eyebrow: "Movement", title: "Purchasing", copy: "Create, approve and receive replenishment orders." },
  accounting: { eyebrow: "Control", title: "Accounting", copy: "Supplier payments and the append-only journal ledger." },
  replenishment: { eyebrow: "Insights", title: "Replenishment", copy: "Explainable stock suggestions using trailing sales velocity." },
  notifications: { eyebrow: "Attention", title: "Operator inbox", copy: "Keep on top of low stock, approvals and transfer updates." },
  ledger: { eyebrow: "Insights", title: "Inventory ledger", copy: "The immutable evidence behind every stock position." },
  reports: { eyebrow: "Insights", title: "Reports & analytics", copy: "Branch, profitability and workflow signals for operational decisions." },
  users: { eyebrow: "Administration", title: "Team access", copy: "Create operator accounts and review their assigned roles." },
};

function initialView(): View {
  const candidate = new URLSearchParams(window.location.search).get("view");
  return candidate && candidate in titles ? candidate as View : "overview";
}
function formatDate(value: string) { return new Date(value).toLocaleString("en-ZW", { dateStyle: "medium", timeStyle: "short" }); }
function errorText(error: unknown, fallback: string) { return error instanceof Error ? error.message : fallback; }
async function createCustomer(name: string, phone: string): Promise<void> { await persistCustomer(name, phone); }

export function App() {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [data, setData] = useState<AppData>(emptyData);
  const [view, setViewState] = useState<View>(initialView);
  const [loading, setLoading] = useState(true);
  const [authBusy, setAuthBusy] = useState(false);
  const [toast, setToast] = useState<Toast>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [confirm, setConfirm] = useState<{ title: string; description: string; action: () => Promise<void> } | null>(null);
  const menuButton = useRef<HTMLButtonElement>(null);

  const hasRole = useCallback((roles: string[]) => roles.includes(user?.role ?? ""), [user]);
  const canSee = useCallback((target: View) => canRoleSeeView(user?.role ?? "", target), [user]);
  const changeView = useCallback((next: View) => {
    if (!canSee(next)) return;
    const url = new URL(window.location.href);
    if (next === "overview") url.searchParams.delete("view"); else url.searchParams.set("view", next);
    window.history.pushState({}, "", url);
    setViewState(next); setMenuOpen(false);
  }, [canSee]);

  const refresh = useCallback(async (activeUser = user) => {
    const [branches, products, suppliers, movements, transfers, purchaseOrders, notifications, customers, approvals, expenses, supplierPayments, journalEntries, pendingSync] = await Promise.all([
      db.branches.toArray(), db.products.toArray(), db.suppliers.toArray(), db.movements.orderBy("createdAt").reverse().toArray(), db.transfers.orderBy("requestedAt").reverse().toArray(), db.purchaseOrders.orderBy("requestedAt").reverse().toArray(), db.notifications.orderBy("createdAt").reverse().toArray(), db.customers.toArray(), db.approvals.toArray(), db.expenses.toArray(), db.supplierPayments.orderBy("createdAt").reverse().toArray(), db.journalEntries.orderBy("createdAt").reverse().toArray(), pendingSyncCount(),
    ]);
    const analytics = ANALYTICS_ROLES.includes(activeUser?.role ?? "");
    const accounting = ACCOUNTING_ROLES.includes(activeUser?.role ?? "");
    const replenishment = REPLENISHMENT_ROLES.includes(activeUser?.role ?? "");
    const [dailySales, profitLoss, branchPerformance, expensesSummary, approvalsSummary, replenishmentSuggestions, adminUsers] = await Promise.all([
      fetchDailySales().catch(() => []), accounting ? fetchProfitLoss().catch(() => null) : Promise.resolve(null), analytics ? fetchBranchPerformance().catch(() => []) : Promise.resolve([]), accounting ? fetchExpensesSummary().catch(() => null) : Promise.resolve(null), analytics ? fetchApprovalsSummary().catch(() => null) : Promise.resolve(null), replenishment ? fetchReplenishmentSuggestions().catch(() => []) : Promise.resolve([]), ["owner", "super_admin"].includes(activeUser?.role ?? "") ? request("/users").catch(() => []) as Promise<AuthUser[]> : Promise.resolve([]),
    ]);
    setData({ branches, products, suppliers, movements, transfers, purchaseOrders, notifications, customers, approvals, expenses, supplierPayments, journalEntries, pendingSync, dailySales, profitLoss, branchPerformance, expensesSummary, approvalsSummary, replenishmentSuggestions, adminUsers });
  }, [user]);

  const sync = useCallback(async (activeUser = user) => {
    try { await loadFromServer(); await refresh(activeUser); const pending = await pendingSyncCount(); setToast(pending ? { tone: "info", message: `${pending} transaction${pending === 1 ? " is" : "s are"} still waiting to sync. Retry after resolving the connection or server error.` } : { tone: "success", message: "Live database connected. Pending transactions were synced." }); }
    catch { await refresh(activeUser); setToast({ tone: "info", message: "Offline mode: cached data is available and new transactions will queue." }); }
  }, [refresh, user]);

  useEffect(() => {
    const init = async () => {
      try { const response = await getCurrentUser(); await prepareOfflineWorkspace(response.user.id); setUser(response.user); await registerDevice(); await sync(response.user); }
      catch (error) { setUser(null); if (error instanceof Error && error.message.includes("queued transactions")) setToast({ tone: "error", message: error.message }); }
      finally { setLoading(false); }
    };
    void init();
  // Authentication is established once; later syncs are triggered by user actions or reconnection.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { const update = () => void sync(); window.addEventListener("online", update); return () => window.removeEventListener("online", update); }, [sync]);
  useEffect(() => { const pop = () => setViewState(initialView()); window.addEventListener("popstate", pop); return () => window.removeEventListener("popstate", pop); }, []);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(null), 6000); return () => window.clearTimeout(timer); }, [toast]);
  useEffect(() => { document.title = user ? `${titles[view].title} · SparePilot Operations` : "Sign in · SparePilot Operations"; }, [user, view]);

  const run = useCallback(async (action: () => Promise<void>, success: string, nextView = view, fallback = "We could not complete that action.") => {
    setBusy(true);
    try { await action(); await refresh(); changeView(nextView); setToast({ tone: "success", message: success }); }
    catch (error) { await refresh().catch(() => undefined); setToast({ tone: "error", message: errorText(error, fallback) }); }
    finally { setBusy(false); }
  }, [changeView, refresh, view]);

  const onLogin = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setAuthBusy(true);
    const form = new FormData(event.currentTarget);
    try { await login(String(form.get("email") ?? ""), String(form.get("password") ?? "")); const response = await getCurrentUser(); await prepareOfflineWorkspace(response.user.id); setUser(response.user); await registerDevice(); await sync(response.user); }
    catch (error) { setToast({ tone: "error", message: errorText(error, "We could not sign you in. Check your email and password, then try again.") }); }
    finally { setAuthBusy(false); }
  };
  const onLogout = async () => { await closeOfflineWorkspace(); await logout(); setUser(null); setData(emptyData); setToast({ tone: "info", message: "You have signed out." }); };
  const closeConfirm = useCallback(() => setConfirm(null), []);

  if (loading) return <LoadingScreen />;
  if (!user) return <Login busy={authBusy} onSubmit={onLogin} toast={toast} />;
  const activeView = canSee(view) ? view : "overview";
  const content = <Workspace view={activeView} data={data} user={user} hasRole={hasRole} run={run} confirm={setConfirm} changeView={changeView} refresh={refresh} setToast={setToast} busy={busy} />;
  return <><AppShell user={user} view={view} data={data} canSee={canSee} changeView={changeView} menuOpen={menuOpen} setMenuOpen={setMenuOpen} menuButton={menuButton} onLogout={onLogout}>{content}</AppShell><ToastMessage toast={toast} onClose={() => setToast(null)} /><ConfirmDialog confirm={confirm} busy={busy} onClose={closeConfirm} onConfirm={() => { if (!confirm) return; const action = confirm.action; setConfirm(null); void run(action, "Action completed."); }} /></>;
}

function LoadingScreen() { return <main className="loading-screen" aria-label="Loading SparePilot Operations"><div className="loading-mark">SP</div><p>Preparing your operations workspace…</p></main>; }
function Login({ busy, onSubmit, toast }: { busy: boolean; onSubmit: (event: FormEvent<HTMLFormElement>) => void; toast: Toast }) { return <main className="auth-shell"><section className="auth-card"><div className="brand-lockup"><span className="brand-mark">SP</span><span>SparePilot <small>Operations</small></span></div><p className="eyebrow">Secure operator sign-in</p><h1>Move stock with confidence.</h1><p className="lede">Sign in to load your operational data. Your device can continue recording eligible work while offline.</p><form className="form-stack" onSubmit={onSubmit}><Field label="Email"><input name="email" type="email" autoComplete="email" required /></Field><Field label="Password"><input name="password" type="password" autoComplete="current-password" required /></Field><button className="button button-primary" disabled={busy}>{busy ? "Signing in…" : "Sign in"}</button></form>{toast?.tone === "error" && <InlineAlert tone="error">{toast.message}</InlineAlert>}<p className="auth-footnote">Protected operational access · Role-based controls</p></section></main>; }

function NavIcon({ view }: { view: View }) { const paths: Record<View, ReactNode> = { overview: <><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z" /><path d="M9 21v-6h6v6" /></>, catalogue: <><path d="M3 7.5 12 3l9 4.5-9 4.5Z" /><path d="M3 7.5V17l9 4 9-4V7.5" /><path d="M12 12v9" /></>, receipt: <><path d="M4 13v7a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-7" /><path d="M12 3v11m0 0-4-4m4 4 4-4" /></>, sale: <><path d="M4 20 20 4" /><path d="M11 4h9v9" /><path d="M4 6v14h14" /></>, transfer: <><path d="M4 7h13m0 0-3-3m3 3-3 3M20 17H7m0 0 3 3m-3-3 3-3" /></>, purchase: <><path d="M4 6h16l-1 15H5Z" /><path d="M8 6a4 4 0 0 1 8 0" /><path d="M12 11v6m-3-3h6" /></>, approval: <><path d="M5 12.5 9.5 17 19 6" /></>, expense: <><circle cx="12" cy="12" r="8" /><path d="M14.5 9.5c-.5-1-1.6-1.5-2.8-1.5-1.6 0-2.7.8-2.7 2 0 3 5.8 1.2 5.8 4 0 1.2-1.2 2-2.8 2-1.3 0-2.5-.6-3-1.7M12 6.5v11" /></>, accounting: <><rect x="4" y="3" width="16" height="18" rx="1" /><path d="M8 8h8M8 12h8M8 16h5" /></>, replenishment: <><path d="M20 12a8 8 0 1 1-2.3-5.7" /><path d="M20 4v5h-5" /></>, reports: <><path d="M4 20V10m5 10V4m6 16v-7m5 7V7" /></>, ledger: <><path d="M5 4h14v16H5z" /><path d="M8 8h8M8 12h8M8 16h8" /></>, notifications: <><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" /></>, users: <><circle cx="9" cy="8" r="3" /><circle cx="17" cy="10" r="2" /><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6M15 15c3 0 5 2 5 5" /></> }; return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[view]}</svg>; }

function getFocusable(container: HTMLElement | null) { return container ? Array.from(container.querySelectorAll<HTMLElement>('button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])')) : []; }

export function AppShell({ user, view, data, canSee, changeView, menuOpen, setMenuOpen, menuButton, onLogout, children }: { user: AuthUser; view: View; data: AppData; canSee: (view: View) => boolean; changeView: (view: View) => void; menuOpen: boolean; setMenuOpen: (value: boolean) => void; menuButton: RefObject<HTMLButtonElement | null>; onLogout: () => void; children: ReactNode }) {
  const navigation: Array<[string, Array<[View, string]>]> = [["Workspace", [["overview", "Overview"]]], ["Inventory", [["catalogue", "Parts & fitment"], ["receipt", "Receive stock"]]], ["Movement", [["sale", "Record sale"], ["transfer", "Branch transfer"], ["purchase", "Purchasing"]]], ["Control", [["approval", "Approvals"], ["expense", "Expenses"], ["accounting", "Accounting"]]], ["Insights", [["replenishment", "Replenishment"], ["reports", "Reports & analytics"], ["ledger", "Audit ledger"]]], ["Attention", [["notifications", "Notifications"], ["users", "Team access"]]]];
  const [collapsed, setCollapsed] = useState(false);
  const [openGroups, setOpenGroups] = useState<string[]>(navigation.map(([label]) => label));
  const mobileNav = useRef<HTMLDivElement>(null);
  useEffect(() => { if (!menuOpen) return; const drawer = mobileNav.current; const restoreTarget = menuButton.current; const focusable = getFocusable(drawer); focusable[0]?.focus(); const handleKey = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); setMenuOpen(false); return; } if (event.key !== "Tab" || focusable.length === 0) return; const first = focusable[0]; const last = focusable[focusable.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }; document.addEventListener("keydown", handleKey); return () => { document.removeEventListener("keydown", handleKey); restoreTarget?.focus(); }; }, [menuButton, menuOpen, setMenuOpen]);
  const nav = <nav className="side-nav" aria-label="Primary navigation">{navigation.map(([label, items]) => { const visible = items.filter(([id]) => canSee(id)); const expanded = openGroups.includes(label); return visible.length ? <section key={label} className={expanded ? "" : "is-collapsed"}><button className="nav-group-toggle" aria-expanded={expanded} onClick={() => setOpenGroups((groups) => expanded ? groups.filter((group) => group !== label) : [...groups, label])}><span>{label}</span><span aria-hidden="true">{expanded ? "−" : "+"}</span></button>{expanded && visible.map(([id, text]) => <button key={id} title={text} className={view === id ? "active" : ""} aria-current={view === id ? "page" : undefined} onClick={() => changeView(id)}><span className="nav-icon"><NavIcon view={id} /></span><span className="nav-label">{text}</span>{id === "notifications" && data.notifications.some((item) => !item.read) && <span className="nav-count">{data.notifications.filter((item) => !item.read).length}</span>}</button>)}</section> : null; })}</nav>;
  const brand = <button className="brand-lockup brand-home" aria-label="SparePilot Operations home" onClick={() => changeView("overview")}><span className="brand-mark">SP</span><span>SparePilot <small>Operations</small></span></button>;
  return <div className={`app-shell ${collapsed ? "nav-collapsed" : ""}`}><aside className="sidebar">{brand}<button className="sidebar-toggle" aria-label={collapsed ? "Expand navigation" : "Collapse navigation"} aria-pressed={collapsed} onClick={() => setCollapsed(!collapsed)}>{collapsed ? "→" : "←"}</button>{nav}<div className="operator"><span className="avatar" aria-hidden="true">{user.full_name.slice(0, 2).toUpperCase()}</span><div><strong>{user.full_name}</strong><small>{user.role.replaceAll("_", " ")}</small></div><button className="icon-button quiet" aria-label="Sign out" onClick={onLogout}>↗</button></div></aside><header className="mobile-header">{brand}<button ref={menuButton} className="menu-button" aria-expanded={menuOpen} aria-controls="mobile-nav" onClick={() => setMenuOpen(!menuOpen)}>{menuOpen ? "Close" : "Menu"}</button></header>{menuOpen && <div ref={mobileNav} id="mobile-nav" className="mobile-nav" role="dialog" aria-modal="true" aria-label="Navigation">{nav}<button className="button button-secondary" onClick={onLogout}>Sign out</button></div>}<main className="workspace">{children}</main></div>;
}

function Workspace({ view, data, user, hasRole, run, confirm, changeView, refresh, setToast, busy }: { view: View; data: AppData; user: AuthUser; hasRole: (roles: string[]) => boolean; run: (action: () => Promise<void>, success: string, nextView?: View, fallback?: string) => Promise<void>; confirm: (value: { title: string; description: string; action: () => Promise<void> } | null) => void; changeView: (view: View) => void; refresh: () => Promise<void>; setToast: (toast: Toast) => void; busy: boolean }) {
  const meta = titles[view]; const warehouse = data.branches.find((branch) => branch.type === "warehouse"); const shop = data.branches.find((branch) => branch.type === "shop");
  const product = (id: string) => data.products.find((item) => item.id === id); const branch = (id: string) => data.branches.find((item) => item.id === id);
  const stock = (productId: string, branchId?: string) => data.movements.filter((item) => item.productId === productId && item.branchId === branchId).reduce((sum, item) => sum + item.quantity, 0);
  const transactionIntro = "Transactions are saved to the operational database, or queued safely on this device when it is offline.";
  let body: ReactNode;
  if (view === "overview") {
    const low = data.products.filter((item) => stock(item.id, shop?.id) <= item.reorderLevel); const sales = data.movements.filter((item) => item.kind === "sale").reduce((sum, item) => sum + (product(item.productId)?.sellingPrice ?? 0) * -item.quantity, 0); const pending = data.approvals.filter((item) => item.status === "pending").length;
    body = <><section className="command-strip"><div><span className="eyebrow">Operational posture</span><h2>{low.length ? `${low.length} stock item${low.length === 1 ? "" : "s"} need attention` : "Stock position is stable"}</h2><p>{data.pendingSync ? `${data.pendingSync} transaction${data.pendingSync === 1 ? " is" : "s are"} waiting to sync.` : "This device is connected and there are no queued transactions."}</p></div><div className="quick-actions"><button className="button button-primary" onClick={() => changeView("sale")}>Record a sale</button><button className="button button-secondary" onClick={() => changeView("transfer")}>Move stock</button></div></section><section className="metric-grid"><Metric label="Parts catalogued" value={data.products.length} detail="with exact vehicle fitment" /><Metric label="Sales recorded" value={money.format(sales)} detail="from the stock ledger" /><Metric label="Pending approvals" value={pending} detail={pending ? "requiring a decision" : "queue is clear"} tone={pending ? "warning" : undefined} /><Metric label="Sync status" value={data.pendingSync ? `${data.pendingSync} queued` : "Synced"} detail="local-first device state" tone={data.pendingSync ? "warning" : "success"} /></section><section className="content-grid"><Panel title="Stock watch" meta={shop?.name ?? "No shop configured"}><RecordList empty="No products need replenishment.">{low.slice(0, 5).map((item) => <Record key={item.id} title={item.name} detail={item.fitment} aside={<Status tone="warning">{stock(item.id, shop?.id)} left</Status>} />)}</RecordList><button className="text-link" onClick={() => changeView("replenishment")}>Review replenishment suggestions →</button></Panel><Panel title="Transfer queue" meta={`${data.transfers.filter((item) => item.status !== "received" && item.status !== "cancelled").length} open`}><RecordList empty="No open transfers.">{data.transfers.filter((item) => item.status !== "received" && item.status !== "cancelled").slice(0, 5).map((item) => <Record key={item.id} title={item.reference} detail={`${product(item.productId)?.name ?? "Part"} · ${item.quantity} units`} aside={<Status>{item.status.replaceAll("_", " ")}</Status>} />)}</RecordList><button className="text-link" onClick={() => changeView("transfer")}>Manage branch transfers →</button></Panel><Panel title="Attention inbox" meta={`${data.notifications.filter((item) => !item.read).length} unread`}><RecordList empty="No unread notifications.">{data.notifications.filter((item) => !item.read).slice(0, 4).map((item) => <Record key={item.id} title={item.title} detail={item.body} />)}</RecordList><button className="text-link" onClick={() => changeView("notifications")}>Open operator inbox →</button></Panel></section></>;
  } else if (view === "catalogue") body = <Catalogue products={data.products} shop={shop} stock={stock} />;
  else if (view === "receipt") body = <TransactionPanel title="Goods receipt" description={transactionIntro}><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); void run(() => recordReceipt(String(f.get("product")), warehouse!.id, Number(f.get("quantity")), String(f.get("supplier"))), "Receipt saved or queued for sync.", "ledger", "We could not save this goods receipt."); }}><Field label="Part"><GlassSelect label="Part" name="product" required options={data.products.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Supplier"><GlassSelect label="Supplier" name="supplier" required options={data.suppliers.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Quantity"><input name="quantity" type="number" min="1" defaultValue="1" required /></Field><FormAction busy={busy}>Post goods receipt</FormAction></form></TransactionPanel>;
  else if (view === "transfer") body = <TransferView data={data} warehouse={warehouse} shop={shop} product={product} hasRole={hasRole} busy={busy} confirm={confirm} run={run} />;
  else if (view === "sale") body = <SaleView data={data} shop={shop} product={product} busy={busy} run={run} />;
  else if (view === "approval") body = <ApprovalsView data={data} user={user} busy={busy} run={run} confirm={confirm} />;
  else if (view === "expense") body = <ExpensesView data={data} busy={busy} run={run} confirm={confirm} />;
  else if (view === "purchase") body = <PurchasingView data={data} hasRole={hasRole} busy={busy} run={run} confirm={confirm} />;
  else if (view === "accounting") body = <AccountingView data={data} busy={busy} run={run} confirm={confirm} />;
  else if (view === "replenishment") body = <ReplenishmentView rows={data.replenishmentSuggestions} />;
  else if (view === "notifications") body = <NotificationsView data={data} busy={busy} run={run} refresh={refresh} setToast={setToast} />;
  else if (view === "reports") body = <ReportsView data={data} />;
  else if (view === "users") body = <UsersView data={data} busy={busy} run={run} />;
  else body = <LedgerView movements={data.movements} product={product} branch={branch} />;
  return <><header className="page-heading"><div>{meta.eyebrow && <p className="eyebrow">{meta.eyebrow}</p>}<h1>{meta.title}</h1></div></header>{getSyncIssues().length > 0 && <Panel title="Sync issues" meta={`${getSyncIssues().length} unresolved`} className="sync-panel"><RecordList>{getSyncIssues().map((issue) => <Record key={issue.id} title={issue.reference} detail={issue.message} aside={<button className="button button-secondary" onClick={() => { dismissSyncIssue(issue.id); void refresh(); }}>Dismiss</button>} />)}</RecordList></Panel>}{body}</>;
}

export function GlassSelect({ label, value, defaultValue, name, required, options, onChange }: { label: string; value?: string; defaultValue?: string; name?: string; required?: boolean; options: Array<{ value: string; label: string }>; onChange?: (value: string) => void }) { const [open, setOpen] = useState(false); const [internalValue, setInternalValue] = useState(defaultValue ?? options[0]?.value ?? ""); const [activeIndex, setActiveIndex] = useState(0); const root = useRef<HTMLDivElement>(null); const trigger = useRef<HTMLButtonElement>(null); const optionRefs = useRef<Array<HTMLButtonElement | null>>([]); const menuId = useId(); const currentValue = value ?? internalValue; const selectedIndex = Math.max(0, options.findIndex((option) => option.value === currentValue)); const selected = options[selectedIndex]; const choose = (index: number) => { const option = options[index]; if (!option) return; if (value === undefined) setInternalValue(option.value); onChange?.(option.value); setOpen(false); trigger.current?.focus(); }; const show = (index = selectedIndex) => { if (!options.length) return; setActiveIndex(index); setOpen(true); }; const onTriggerKeyDown = (event: ReactKeyboardEvent<HTMLButtonElement>) => { if (event.key === "ArrowDown" || event.key === "ArrowUp" || event.key === "Home" || event.key === "End") { event.preventDefault(); show(event.key === "End" || event.key === "ArrowUp" ? options.length - 1 : 0); } }; const onOptionKeyDown = (event: ReactKeyboardEvent<HTMLButtonElement>, index: number) => { if (event.key === "Escape") { event.preventDefault(); setOpen(false); trigger.current?.focus(); } else if (event.key === "ArrowDown" || event.key === "ArrowUp") { event.preventDefault(); setActiveIndex((index + (event.key === "ArrowDown" ? 1 : -1) + options.length) % options.length); } else if (event.key === "Home" || event.key === "End") { event.preventDefault(); setActiveIndex(event.key === "Home" ? 0 : options.length - 1); } else if (event.key === "Enter" || event.key === " ") { event.preventDefault(); choose(index); } else if (event.key === "Tab") setOpen(false); }; useEffect(() => { const close = (event: MouseEvent) => { if (!root.current?.contains(event.target as Node)) setOpen(false); }; document.addEventListener("mousedown", close); return () => document.removeEventListener("mousedown", close); }, []); useEffect(() => { if (open) optionRefs.current[activeIndex]?.focus(); }, [activeIndex, open]); return <div className="glass-select" ref={root}>{name && <input type="hidden" name={name} value={currentValue} required={required} />}<button ref={trigger} type="button" className="glass-select-trigger" aria-label={label} aria-haspopup="listbox" aria-controls={menuId} aria-expanded={open} disabled={!options.length} onKeyDown={onTriggerKeyDown} onClick={() => open ? setOpen(false) : show()}>{selected?.label ?? "No options"}<span aria-hidden="true">⌄</span></button>{open && <div id={menuId} className="glass-select-menu" role="listbox" aria-label={label}>{options.map((option, index) => <button ref={(node) => { optionRefs.current[index] = node; }} key={option.value} type="button" role="option" aria-selected={option.value === currentValue} tabIndex={index === activeIndex ? 0 : -1} className={option.value === currentValue ? "selected" : ""} onMouseEnter={() => setActiveIndex(index)} onKeyDown={(event) => onOptionKeyDown(event, index)} onClick={() => choose(index)}>{option.label}</button>)}</div>}</div>; }
function Catalogue({ products, shop, stock }: { products: Product[]; shop?: Branch; stock: (id: string, branch?: string) => number }) { const [query, setQuery] = useState(""); const [filter, setFilter] = useState<"all" | "low">("all"); const rows = products.filter((item) => (`${item.name} ${item.brand} ${item.sku} ${item.fitment}`).toLowerCase().includes(query.toLowerCase()) && (filter === "all" || stock(item.id, shop?.id) <= item.reorderLevel)); return <Panel title="Fitment-first catalogue"><div className="table-tools"><label className="sr-only" htmlFor="catalogue-search">Search catalogue</label><input id="catalogue-search" type="search" placeholder="Search part, SKU, brand or fitment" value={query} onChange={(event) => setQuery(event.target.value)} /><GlassSelect label="Stock filter" value={filter} onChange={(value) => setFilter(value as "all" | "low")} options={[{ value: "all", label: "All stock states" }, { value: "low", label: "Low shop stock" }]} /></div><div className="table-wrap"><table><thead><tr><th>Part / SKU</th><th>Vehicle fitment</th><th>Shop</th><th>Sell</th></tr></thead><tbody>{rows.map((item) => <tr key={item.id}><td><strong>{item.name}</strong><small>{item.brand} · {item.sku}</small></td><td>{item.fitment}</td><td>{stock(item.id, shop?.id)}</td><td>{money.format(item.sellingPrice)}</td></tr>)}</tbody></table></div>{rows.length === 0 && <Empty title="No matching parts" description="Try a broader search or clear the stock filter." />}</Panel>; }
function TransferView({ data, warehouse, shop, product, hasRole, busy, confirm, run }: { data: AppData; warehouse?: Branch; shop?: Branch; product: (id: string) => Product | undefined; hasRole: (roles: string[]) => boolean; busy: boolean; confirm: (value: { title: string; description: string; action: () => Promise<void> }) => void; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void> }) { const requested = data.transfers.filter((item) => item.status === "requested"); const inTransit = data.transfers.filter((item) => item.status === "in_transit"); return <><TransactionPanel title="Request a branch transfer" description="A request does not move stock. Warehouse fulfilment and shop receipt are recorded separately."><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); void run(() => recordTransfer(String(f.get("product")), warehouse!.id, shop!.id, Number(f.get("quantity"))), "Transfer requested or queued for sync.", "transfer", "We could not request this transfer."); }}><Field label="Part"><GlassSelect label="Part" name="product" required options={data.products.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Quantity"><input name="quantity" type="number" min="1" defaultValue="1" required /></Field><FormAction busy={busy}>Request transfer</FormAction></form></TransactionPanel><Panel title="Awaiting fulfilment" meta={`${requested.length} pending`}><RecordList empty="No transfers are waiting for fulfilment.">{requested.map((item) => <Record key={item.id} title={item.reference} detail={`${product(item.productId)?.name ?? "Part"} · ${item.quantity} units`} aside={<div className="record-actions">{hasRole(TRANSFER_FULFIL_ROLES) && <button className="button button-secondary" disabled={busy} onClick={() => confirm({ title: "Fulfil transfer?", description: "This moves stock out of the warehouse and starts the in-transit stage.", action: () => fulfilTransfer(item.id, item.reference, item.version) })}>Fulfil</button>}<button className="button button-danger" disabled={busy} onClick={() => confirm({ title: "Cancel transfer?", description: "This request will be cancelled and cannot be received.", action: () => cancelTransfer(item.id) })}>Cancel</button></div>} />)}</RecordList></Panel><Panel title="In transit" meta={`${inTransit.length} awaiting receipt`}><RecordList empty="Nothing is currently in transit.">{inTransit.map((item) => <Record key={item.id} title={item.reference} detail={`${product(item.productId)?.name ?? "Part"} · ${item.quantity} units`} aside={hasRole(TRANSFER_RECEIVE_ROLES) ? <button className="button button-secondary" disabled={busy} onClick={() => confirm({ title: "Receive transfer?", description: "This posts the stock receipt into the destination branch.", action: () => receiveTransfer(item.id, item.reference, item.version) })}>Receive</button> : <Status>Awaiting receipt</Status>} />)}</RecordList></Panel></>; }
function SaleView({ data, shop, product, busy, run }: { data: AppData; shop?: Branch; product: (id: string) => Product | undefined; busy: boolean; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void> }) { return <><TransactionPanel title="Counter sale" description="Only stock available at the shop can be issued. A customer is optional for walk-in sales."><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); const selected = product(String(f.get("product"))); if (!selected || !shop) return; void run(() => recordSale(selected, shop.id, Number(f.get("quantity")), String(f.get("customer")) || null), "Sale saved or queued for sync.", "ledger", "We could not record this sale."); }}><Field label="Part"><GlassSelect label="Part" name="product" required options={data.products.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Quantity"><input name="quantity" type="number" min="1" defaultValue="1" required /></Field><Field label="Customer" hint="Optional — leave blank for a walk-in customer."><GlassSelect label="Customer" name="customer" options={[{ value: "", label: "Walk-in customer" }, ...data.customers.map((item) => ({ value: item.id, label: item.name }))]} /></Field><FormAction busy={busy}>Issue sale receipt</FormAction></form></TransactionPanel><Panel title="Add a customer" meta={`${data.customers.length} on file`}><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); void run(() => createCustomer(String(f.get("name")), String(f.get("phone"))), "Customer added.", "sale", "We could not add that customer."); }}><Field label="Customer name"><input name="name" required /></Field><Field label="Phone"><input name="phone" type="tel" /></Field><FormAction busy={busy}>Add customer</FormAction></form></Panel></>; }
function ApprovalsView({ data, user, busy, run, confirm }: { data: AppData; user: AuthUser; busy: boolean; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void>; confirm: (value: { title: string; description: string; action: () => Promise<void> }) => void }) { return <><TransactionPanel title="Request an approval" description="Create a traceable request for decisions that should not be made directly."><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); void run(() => createApproval(String(f.get("type")), String(f.get("subject")), user.full_name, String(f.get("approver")), String(f.get("priority"))), "Approval request sent.", "approval", "We could not send the approval request."); }}><Field label="Request type"><GlassSelect label="Request type" name="type" options={[{ value: "stock adjustment", label: "stock adjustment" }, { value: "price change", label: "price change" }, { value: "expense", label: "expense" }]} /></Field><Field label="Approver"><input name="approver" required /></Field><Field label="Subject"><input name="subject" required /></Field><Field label="Priority"><GlassSelect label="Priority" name="priority" options={[{ value: "normal", label: "Normal" }, { value: "high", label: "High" }]} /></Field><FormAction busy={busy}>Send for approval</FormAction></form></TransactionPanel><Panel title="Approval queue" meta={`${data.approvals.filter((item) => item.status === "pending").length} pending`}><RecordList empty="There are no approval requests yet.">{data.approvals.map((item) => <Record key={item.id} title={item.subject} detail={`${item.requester} · ${item.approver}`} aside={item.status === "pending" ? <div className="record-actions"><button className="button button-secondary" disabled={busy} onClick={() => confirm({ title: "Approve this request?", description: "This updates the linked operational workflow.", action: () => approveApproval(item.id) })}>Approve</button><button className="button button-danger" disabled={busy} onClick={() => confirm({ title: "Reject this request?", description: "The requester will see that this decision was declined.", action: () => rejectApproval(item.id) })}>Reject</button></div> : <Status tone={item.isOverdue ? "warning" : "neutral"}>{item.isOverdue ? "overdue" : item.status}</Status>} />)}</RecordList></Panel></>; }
function ExpensesView({ data, busy, run, confirm }: { data: AppData; busy: boolean; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void>; confirm: (value: { title: string; description: string; action: () => Promise<void> }) => void }) { return <><TransactionPanel title="Record an operating expense" description="Expense entries require approval before a journal entry is posted."><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); void run(() => createExpense(String(f.get("branch")), String(f.get("category")), Number(f.get("amount")), String(f.get("description"))), "Expense recorded.", "expense", "We could not record that expense."); }}><Field label="Branch"><GlassSelect label="Branch" name="branch" options={data.branches.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Category"><GlassSelect label="Category" name="category" options={[{ value: "Delivery", label: "Delivery" }, { value: "Utilities", label: "Utilities" }, { value: "Maintenance", label: "Maintenance" }]} /></Field><Field label="Amount (USD)"><input name="amount" type="number" min="0.01" step="0.01" required /></Field><Field label="Description"><input name="description" required /></Field><FormAction busy={busy}>Record expense</FormAction></form></TransactionPanel><Panel title="Expense queue" meta={`${data.expenses.filter((item) => item.status === "pending").length} pending`}><RecordList empty="No expenses have been recorded.">{data.expenses.map((item) => <Record key={item.id} title={`${item.category} · ${money.format(item.amount)}`} detail={item.description} aside={item.status === "pending" ? <div className="record-actions"><button className="button button-secondary" disabled={busy} onClick={() => confirm({ title: "Approve this expense?", description: "Approving posts a journal entry for this expense.", action: () => approveExpense(item.id) })}>Approve</button><button className="button button-danger" disabled={busy} onClick={() => confirm({ title: "Reject this expense?", description: "The expense will not be posted to the journal.", action: () => rejectExpense(item.id) })}>Reject</button></div> : <Status>{item.status}</Status>} />)}</RecordList></Panel></>; }
function PurchasingView({ data, hasRole, busy, run, confirm }: { data: AppData; hasRole: (roles: string[]) => boolean; busy: boolean; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void>; confirm: (value: { title: string; description: string; action: () => Promise<void> }) => void }) { return <><TransactionPanel title="Request a purchase order" description="Create a replenishment request. Receipt remains a separate, controlled stock event."><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); void run(() => createPurchaseOrder(String(f.get("supplier")), String(f.get("branch")), String(f.get("notes")), [{ productId: String(f.get("product")), quantity: Number(f.get("quantity")), unitCost: Number(f.get("unitCost")) }]), "Purchase order queued or synced.", "purchase", "We could not create that purchase order."); }}><Field label="Supplier"><GlassSelect label="Supplier" name="supplier" options={data.suppliers.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Receiving branch"><GlassSelect label="Receiving branch" name="branch" options={data.branches.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Part"><GlassSelect label="Part" name="product" options={data.products.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Quantity"><input name="quantity" type="number" min="1" defaultValue="1" required /></Field><Field label="Unit cost (USD)"><input name="unitCost" type="number" min="0.01" step="0.01" defaultValue="5" required /></Field><Field label="Notes"><input name="notes" /></Field><FormAction busy={busy}>Create purchase order</FormAction></form></TransactionPanel><Panel title="Open purchase orders" meta={`${data.purchaseOrders.filter((item) => item.status !== "received").length} open`}><RecordList empty="No purchase orders have been created.">{data.purchaseOrders.map((item) => { const supplier = data.suppliers.find((entry) => entry.id === item.supplierId); const action = item.status === "requested" && hasRole(PURCHASE_ORDER_APPROVE_ROLES) ? <button className="button button-secondary" disabled={busy} onClick={() => confirm({ title: "Approve purchase order?", description: "This makes the order ready to receive.", action: () => approvePurchaseOrder(item.id) })}>Approve</button> : item.status === "approved" ? <button className="button button-secondary" disabled={busy} onClick={() => confirm({ title: "Receive purchase order?", description: "This posts inventory and accounting entries for the order.", action: () => receivePurchaseOrder(item.id, item.reference, item.version) })}>Receive</button> : <Status>{item.status}</Status>; return <Record key={item.id} title={item.reference} detail={`${supplier?.name ?? "Supplier"}${item.notes ? ` · ${item.notes}` : ""}`} aside={action} />; })}</RecordList></Panel></>; }
function AccountingView({ data, busy, confirm }: { data: AppData; busy: boolean; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void>; confirm: (value: { title: string; description: string; action: () => Promise<void> }) => void }) { return <><TransactionPanel title="Record a supplier payment" description="Supplier payments create an auditable cash-out record in the journal."><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); const amount = Number(f.get("amount")); confirm({ title: `Record ${money.format(amount)} payment?`, description: "This posts a supplier-payment journal entry.", action: () => createSupplierPayment(String(f.get("supplier")), String(f.get("purchaseOrder")) || null, amount, String(f.get("method")), String(f.get("notes"))) }); }}><Field label="Supplier"><GlassSelect label="Supplier" name="supplier" options={data.suppliers.map((item) => ({ value: item.id, label: item.name }))} /></Field><Field label="Purchase order" hint="Optional"><GlassSelect label="Purchase order" name="purchaseOrder" options={[{ value: "", label: "Not linked" }, ...data.purchaseOrders.map((item) => ({ value: item.id, label: item.reference }))]} /></Field><Field label="Amount (USD)"><input name="amount" type="number" min="0.01" step="0.01" required /></Field><Field label="Method"><GlassSelect label="Method" name="method" options={[{ value: "bank", label: "Bank transfer" }, { value: "cash", label: "Cash" }, { value: "mobile_money", label: "Mobile money" }]} /></Field><Field label="Notes"><input name="notes" /></Field><FormAction busy={busy}>Record payment</FormAction></form></TransactionPanel><Panel title="Supplier payments" meta={`${data.supplierPayments.length} recorded`}><RecordList empty="No supplier payments have been recorded.">{data.supplierPayments.map((item) => <Record key={item.id} title={`${item.reference} · ${money.format(item.amount)}`} detail={`${data.suppliers.find((entry) => entry.id === item.supplierId)?.name ?? "Supplier"} · ${item.method} · ${formatDate(item.createdAt)}`} />)}</RecordList></Panel><Panel title="Journal ledger" meta={`${data.journalEntries.length} entries`}><LedgerRows rows={data.journalEntries} /></Panel></>; }
function ReplenishmentView({ rows }: { rows: ReplenishmentSuggestion[] }) { return <Panel title="Reorder suggestions"><div className="table-wrap"><table><thead><tr><th>Part</th><th>Branch</th><th>Stock</th><th>30-day sales</th><th>Days of cover</th><th>Suggested reorder</th><th>Status</th></tr></thead><tbody>{rows.map((item) => <tr key={`${item.product_id}-${item.branch_id}`}><td>{item.product_name}</td><td>{item.branch_name}</td><td>{item.current_stock}</td><td>{item.sales_last_30_days}</td><td>{item.days_of_cover ?? "—"}</td><td>{item.suggested_reorder_quantity}</td><td><Status>{item.urgent ? "Reorder" : item.needs_reorder ? "Low" : "OK"}</Status></td></tr>)}</tbody></table></div>{!rows.length && <Empty title="No replenishment data yet" description="Suggestions will appear after inventory and sales data has been synced." />}</Panel>; }
function NotificationsView({ data, busy, run, refresh, setToast }: { data: AppData; busy: boolean; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void>; refresh: () => Promise<void>; setToast: (toast: Toast) => void }) { return <>{pushNotificationsAvailable() && <Panel title="Push notifications" meta="Optional"><p>Get alerted when stock runs low or a transfer needs attention.</p><button className="button button-secondary" onClick={() => { void enablePushNotifications().then(() => setToast({ tone: "success", message: "Push notifications enabled." })).catch((error: unknown) => setToast({ tone: "error", message: errorText(error, "We could not enable push notifications.") })); }}>Enable push notifications</button></Panel>}<Panel title="Operator inbox" meta={`${data.notifications.filter((item) => !item.read).length} unread`}><RecordList empty="There are no notifications yet.">{data.notifications.map((item) => <Record key={item.id} title={item.title} detail={`${item.body} · ${formatDate(item.createdAt)}`} aside={item.read ? <Status tone="success">Read</Status> : <button className="button button-secondary" disabled={busy} onClick={() => void run(() => markNotificationRead(item.id), "Notification marked as read.", "notifications", "We could not mark this notification as read.")}>Mark read</button>} />)}</RecordList></Panel></>; }
function ReportsView({ data }: { data: AppData }) { return <div className="report-stack">{data.profitLoss && <Panel title="Profit & loss" meta={data.profitLoss.start ?? "All time"}><section className="metric-grid compact"><Metric label="Revenue" value={money.format(data.profitLoss.revenue)} /><Metric label="Purchase cost" value={money.format(data.profitLoss.purchase_cost)} /><Metric label="Expenses" value={money.format(data.profitLoss.expenses)} /><Metric label="Net profit" value={money.format(data.profitLoss.net_profit)} tone={data.profitLoss.net_profit >= 0 ? "success" : "warning"} /></section></Panel>}{data.branchPerformance.length > 0 && <Panel title="Branch performance"><div className="table-wrap"><table><thead><tr><th>Branch</th><th>Sales</th><th>Stock value</th><th>Low-stock parts</th></tr></thead><tbody>{data.branchPerformance.map((item) => <tr key={item.branch_id}><td>{item.branch_name}</td><td>{money.format(item.sales_total)} ({item.sales_count})</td><td>{money.format(item.stock_value)}</td><td>{item.low_stock_count}</td></tr>)}</tbody></table></div></Panel>}{data.approvalsSummary && <Panel title="Approval bottlenecks"><section className="metric-grid compact"><Metric label="Pending" value={data.approvalsSummary.pending_count} /><Metric label="Overdue" value={data.approvalsSummary.overdue_count} tone={data.approvalsSummary.overdue_count ? "warning" : undefined} /><Metric label="Average resolution" value={data.approvalsSummary.avg_resolution_hours == null ? "—" : `${data.approvalsSummary.avg_resolution_hours.toFixed(1)}h`} /></section></Panel>}{data.expensesSummary && <Panel title="Expenses by category" meta={`${money.format(data.expensesSummary.total_approved)} approved`}><div className="table-wrap"><table><thead><tr><th>Category</th><th>Status</th><th>Count</th><th>Total</th></tr></thead><tbody>{data.expensesSummary.by_category.map((item) => <tr key={`${item.category}-${item.status}`}><td>{item.category}</td><td><Status>{item.status}</Status></td><td>{item.count}</td><td>{money.format(item.total)}</td></tr>)}</tbody></table></div></Panel>}<Panel title="Daily sales" meta={`${data.dailySales.length} days recorded`}><div className="table-wrap"><table><thead><tr><th>Day</th><th>Sales count</th><th>Sales total</th></tr></thead><tbody>{data.dailySales.map((item) => <tr key={item.day}><td>{item.day}</td><td>{item.sales_count}</td><td>{money.format(item.sales_total)}</td></tr>)}</tbody></table></div>{!data.dailySales.length && <Empty title="No sales data yet" description="Daily sales will appear after the first transaction is recorded." />}</Panel></div>; }
function UsersView({ data, busy, run }: { data: AppData; busy: boolean; run: (action: () => Promise<void>, success: string, next?: View, fallback?: string) => Promise<void> }) { return <><TransactionPanel title="Create an operator account" description="Grant only the access an operator needs. Backend authorization remains authoritative."><form className="form-grid" onSubmit={(event) => { event.preventDefault(); const f = new FormData(event.currentTarget); void run(() => request("/users", { method: "POST", body: JSON.stringify({ full_name: String(f.get("fullName")), email: String(f.get("email")), password: String(f.get("password")), role: String(f.get("role")), branch_id: String(f.get("branch")) || null }) }).then(() => undefined), "User account created.", "users", "We could not create that user."); }}><Field label="Full name"><input name="fullName" required /></Field><Field label="Email"><input name="email" type="email" required /></Field><Field label="Temporary password"><input name="password" type="password" minLength={8} required /></Field><Field label="Role"><GlassSelect label="Role" name="role" options={[{ value: "owner", label: "Owner" }, { value: "accountant", label: "Accountant" }, { value: "store_keeper", label: "Store keeper" }, { value: "shop_manager", label: "Shop manager" }, { value: "cashier", label: "Cashier" }, { value: "super_admin", label: "Super admin" }]} /></Field><Field label="Assigned branch"><GlassSelect label="Assigned branch" name="branch" options={[{ value: "", label: "Unassigned" }, ...data.branches.map((item) => ({ value: item.id, label: item.name }))]} /></Field><FormAction busy={busy}>Create user</FormAction></form></TransactionPanel><Panel title="Operator roster" meta={`${data.adminUsers.length} accounts`}><RecordList empty="No operator accounts are available.">{data.adminUsers.map((item) => <Record key={item.id} title={item.full_name} detail={`${item.email} · ${data.branches.find((branch) => branch.id === item.branch_id)?.name ?? "Unassigned"}`} aside={<Status tone={item.is_active ? "success" : "error"}>{item.is_active ? item.role.replaceAll("_", " ") : "Disabled"}</Status>} />)}</RecordList></Panel></>; }
function LedgerView({ movements, product, branch }: { movements: StockMovement[]; product: (id: string) => Product | undefined; branch: (id: string) => Branch | undefined }) { return <Panel title="Movement evidence" meta="Append-only · newest first"><RecordList empty="No inventory movements have been recorded.">{movements.map((item) => <Record key={item.id} title={`${product(item.productId)?.name ?? "Part"} · ${item.quantity > 0 ? "+" : ""}${item.quantity}`} detail={`${branch(item.branchId)?.name ?? "Branch"} · ${item.kind.replaceAll("_", " ")} · ${item.reference} · ${formatDate(item.createdAt)}`} aside={<Status tone={item.quantity > 0 ? "success" : "warning"}>{item.kind.replaceAll("_", " ")}</Status>} />)}</RecordList></Panel>; }
function LedgerRows({ rows }: { rows: JournalEntry[] }) { return <RecordList empty="No journal entries have been posted.">{rows.map((item) => <Record key={item.id} title={`${item.reference} · ${item.amount >= 0 ? "+" : ""}${money.format(item.amount)}`} detail={`${item.entryType.replaceAll("_", " ")} · ${item.description} · ${formatDate(item.createdAt)}`} aside={<Status tone={item.amount >= 0 ? "success" : "warning"}>{item.amount >= 0 ? "Credit" : "Debit"}</Status>} />)}</RecordList>; }
function TransactionPanel({ title, description, children }: { title: string; description: string; children: ReactNode }) { return <Panel title={title} className="transaction-panel"><p className="panel-description">{description}</p>{children}</Panel>; }
function Panel({ title, meta, children, className = "" }: { title: string; meta?: string; children: ReactNode; className?: string }) { return <section className={`panel ${className}`}><header className="panel-heading"><h2>{title}</h2>{meta && <span>{meta}</span>}</header>{children}</section>; }
function Field({ label, hint, children }: { label: string; hint?: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function FormAction({ busy, children }: { busy: boolean; children: ReactNode }) { return <div className="form-action"><button className="button button-primary" disabled={busy}>{busy ? "Working…" : children}</button></div>; }
function Metric({ label, value, detail, tone }: { label: string; value: ReactNode; detail?: string; tone?: "success" | "warning" }) { return <section className={`metric ${tone ? `metric-${tone}` : ""}`}><small>{label}</small><strong>{value}</strong>{detail && <span>{detail}</span>}</section>; }
function RecordList({ children, empty, }: { children?: ReactNode; empty?: string }) { const items = Array.isArray(children) ? children : [children]; return items.filter(Boolean).length ? <div className="record-list">{children}</div> : <Empty title={empty ?? "Nothing to show"} description="New records will appear here when available." />; }
function Record({ title, detail, aside }: { title: string; detail: string; aside?: ReactNode }) { return <article className="record"><div><strong>{title}</strong><small>{detail}</small></div>{aside && <div className="record-aside">{aside}</div>}</article>; }
function Status({ children, tone = "neutral" }: { children: ReactNode; tone?: "neutral" | "success" | "warning" | "error" }) { return <span className={`status status-${tone}`}>{children}</span>; }
function Empty({ title, description }: { title: string; description: string }) { return <div className="empty-state"><strong>{title}</strong><p>{description}</p></div>; }
function InlineAlert({ tone, children }: { tone: "info" | "error"; children: ReactNode }) { return <div className={`inline-alert inline-alert-${tone}`} role={tone === "error" ? "alert" : undefined}>{children}</div>; }
function ToastMessage({ toast, onClose }: { toast: Toast; onClose: () => void }) { return toast ? <div className={`toast toast-${toast.tone}`} role={toast.tone === "error" ? "alert" : "status"}><span>{toast.message}</span><button aria-label="Dismiss notification" onClick={onClose}>×</button></div> : null; }
export function ConfirmDialog({ confirm, busy, onClose, onConfirm }: { confirm: { title: string; description: string } | null; busy: boolean; onClose: () => void; onConfirm: () => void }) { const dialog = useRef<HTMLElement>(null); const previousFocus = useRef<HTMLElement | null>(null); useEffect(() => { if (!confirm) return; previousFocus.current = document.activeElement as HTMLElement | null; const focusable = getFocusable(dialog.current); focusable[0]?.focus(); const handleKey = (event: KeyboardEvent) => { if (event.key === "Escape" && !busy) { event.preventDefault(); onClose(); return; } if (event.key !== "Tab" || focusable.length === 0) return; const first = focusable[0]; const last = focusable[focusable.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }; window.addEventListener("keydown", handleKey); return () => { window.removeEventListener("keydown", handleKey); previousFocus.current?.focus(); }; }, [busy, confirm, onClose]); if (!confirm) return null; return <div className="dialog-backdrop" role="presentation"><section ref={dialog} className="dialog" role="alertdialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-description"><p className="eyebrow">Confirm action</p><h2 id="dialog-title">{confirm.title}</h2><p id="dialog-description">{confirm.description}</p><div className="dialog-actions"><button className="button button-secondary" onClick={onClose} disabled={busy}>Cancel</button><button className="button button-primary" onClick={onConfirm} disabled={busy}>{busy ? "Working…" : "Confirm"}</button></div></section></div>; }
